// Define the latitude and longitude coordinates of the two points
var lat1 = 51.5;
var lon1 = -0.09;
var lat2 = 52.5;
var lon2 = -1.09;
// Calculate the distance between the two points using the formula
var distance = Math.acos(Math.sin(lat1 * Math.PI / 180) * Math.sin(lat2 * Math.PI / 180) + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.cos((lon2 - lon1) * Math.PI / 180)) * 6371;
// Display the distance in kilometers
console.log(distance);
