To create a program in C++ that allows users to input their own summer bucket list items and sorts the table based on different criteria, you can use arrays and sorting algorithms. Here is a sample code that implements the required features:
```
#include <iostream>
#include <string>
#include <algorithm>
#include <ctime>
using namespace std;
struct BucketListItem {
    string name;
    string location;
    string date;
    string notes;
};
const int MAX_ITEMS = 20;
BucketListItem bucketList[MAX_ITEMS];
int itemCount = 0;
void addItem() {
    if (itemCount >= MAX_ITEMS) {
        cout << "The bucket list is full." << endl;
        return;
    }
    BucketListItem item;
    cout << "Enter the activity name: ";
    getline(cin, item.name);
    cout << "Enter the location: ";
    getline(cin, item.location);
    cout << "Enter the date (MM/DD/YYYY): ";
    getline(cin, item.date);
    cout << "Enter the notes: ";
    getline(cin, item.notes);
    bucketList[itemCount++] = item;
}
void displayList() {
    cout << "Bucket List:" << endl;
    cout << "-------------------------------------------------------" << endl;
    cout << "Name\t\tLocation\tDate\t\tNotes" << endl;
    cout << "-------------------------------------------------------" << endl;
    for (int i = 0; i < itemCount; i++) {
        cout << bucketList[i].name << "\t\t" << bucketList[i].location << "\t\t" << bucketList[i].date << "\t" << bucketList[i].notes << endl;
    }
    cout << "-------------------------------------------------------" << endl;
}
bool compareByName(const BucketListItem& a, const BucketListItem& b) {
    return a.name < b.name;
}
bool compareByLocation(const BucketListItem& a, const BucketListItem& b) {
    return a.location < b.location;
}
bool compareByDate(const BucketListItem& a, const BucketListItem& b) {
    return a.date < b.date;
}
void sortList() {
    int choice;
    cout << "Sort by:" << endl;
    cout << "1. Name" << endl;
    cout << "2. Location" << endl;
    cout << "3. Date" << endl;
    cout << "Enter your choice: ";
    cin >> choice;
    switch (choice) {
        case 1:
            sort(bucketList, bucketList + itemCount, compareByName);
            break;
        case 2:
            sort(bucketList, bucketList + itemCount, compareByLocation);
            break;
        case 3:
            sort(bucketList, bucketList + itemCount, compareByDate);
            break;
        default:
            cout << "Invalid choice." << endl;
            break;
    }
}
int daysUntil(const string& dateStr) {
    time_t now = time(0);
    struct tm timeStruct = *localtime(&now);
    int year, month, day;
    sscanf(dateStr.c_str(), "%d/%d/%d", &month, &day, &year);
    timeStruct.tm_year = year - 1900;
    timeStruct.tm_mon = month - 1;
    timeStruct.tm_mday = day;
    time_t date = mktime(&timeStruct);
    double seconds = difftime(date, now);
    return static_cast<int>(seconds / (60 * 60 * 24));
}
void highlightUpcoming() {
    cout << "Upcoming activities:" << endl;
    cout << "-------------------------------------------------------" << endl;
    cout << "Name\t\tLocation\tDate\t\tNotes" << endl;
    cout << "-------------------------------------------------------" << endl;
    for (int i = 0; i < itemCount; i++) {
        int days = daysUntil(bucketList[i].date);
        if (days >= 0 && days <= 7) {
            cout << bucketList[i].name << "\t\t" << bucketList[i].location << "\t\t" << bucketList[i].date << "\t" << bucketList[i].notes << endl;
        }
    }
    cout << "-------------------------------------------------------" << endl;
}
void editItem() {
    int index;
    cout << "Enter the index of the item to edit: ";
    cin >> index;
    cin.ignore();
    if (index < 0 || index >= itemCount) {
        cout << "Invalid index." << endl;
        return;
    }
    BucketListItem& item = bucketList[index];
    cout << "Enter the new activity name (or press enter to keep the old one): ";
    string name;
    getline(cin, name);
    if (!name.empty()) {
        item.name = name;
    }
    cout << "Enter the new location (or press enter to keep the old one): ";
    string location;
    getline(cin, location);
    if (!location.empty()) {
        item.location = location;
    }
    cout << "Enter the new date (MM/DD/YYYY) (or press enter to keep the old one): ";
    string date;
    getline(cin, date);
    if (!date.empty()) {
        item.date = date;
    }
    cout << "Enter the new notes (or press enter to keep the old ones): ";
    string notes;
    getline(cin, notes);
    if (!notes.empty()) {
        item.notes = notes;
    }
}
void deleteItem() {
    int index;
    cout << "Enter the index of the item to delete: ";
    cin >> index;
    cin.ignore();
    if (index < 0 || index >= itemCount) {
        cout << "Invalid index." << endl;
        return;
    }
    for (int i = index; i < itemCount - 1; i++) {
        bucketList[i] = bucketList[i + 1];
    }
    itemCount--;
}
int main() {
    int choice;
    do {
        cout << "Bucket List Manager" << endl;
        cout << "1. Add item" << endl;
        cout << "2. Display list" << endl;
        cout << "3. Sort list" << endl;
        cout << "4. Highlight upcoming" << endl;
        cout << "5. Edit item" << endl;
        cout << "6. Delete item" << endl;
        cout << "0. Exit" << endl;
        cout << "Enter your choice: ";
        cin >> choice;
        cin.ignore();
        switch (choice) {
            case 1:
                addItem();
                break;
            case 2:
                displayList();
                break;
            case 3:
                sortList();
                break;
            case 4:
                highlightUpcoming();
                break;
            case 5:
                editItem();
                break;
            case 6:
                deleteItem();
                break;
            case 0:
                cout << "Goodbye!" << endl;
                break;
            default:
                cout << "Invalid choice." << endl;
                break;
        }
    } while (choice != 0);
    return 0;
}
```
This code defines a `BucketListItem` struct that holds the information for each item in the bucket list. The `MAX_ITEMS` constant and `bucketList` array are used to store the items. The `itemCount` variable keeps track of the number of items in the list.
The `addItem()` function prompts the user for the information for a new item and adds it to the list if there is room.
The `displayList()` function prints the contents of the list in a table format.
The `compareByName()`, `compareByLocation()`, and `compareByDate()` functions are used by the `sort()` function to sort the list based on different criteria.
The `sortList()` function prompts the user for the sorting criteria and calls the appropriate sorting function.
The `daysUntil()` function calculates the number of days until a given date.
The `highlightUpcoming()` function prints a table of the items that are coming up soon (within 7 days).
The `editItem()` function prompts the user for the index of an item to edit and then prompts for the new information for that item.
The `deleteItem()` function prompts the user for the index of an item to delete and then removes that item from the list.
The `main()` function displays a menu of options and calls the appropriate function based on the user's choice. The menu is displayed repeatedly until the user chooses to exit.

