Go is a great language for implementing networking in business applications due to its simplicity, concurrency, and performance. It has built-in libraries for handling TCP, UDP, and HTTP protocols, making it easy to create networked applications.
Here is an example of Go code for establishing a TCP connection between a client and server:
Server code:
```
package main
import (
    "fmt"
    "net"
)
func main() {
    // Listen for incoming connections
    listener, err := net.Listen("tcp", ":8080")
    if err != nil {
        fmt.Println("Error listening:", err)
        return
    }
    defer listener.Close()
    fmt.Println("Server started, listening on port 8080")
    for {
        // Accept incoming connections
        conn, err := listener.Accept()
        if err != nil {
            fmt.Println("Error accepting:", err)
            continue
        }
        // Handle the connection in a new goroutine
        go handleConnection(conn)
    }
}
func handleConnection(conn net.Conn) {
    // Close the connection when the function returns
    defer conn.Close()
    // Read from the connection
    buffer := make([]byte, 1024)
    n, err := conn.Read(buffer)
    if err != nil {
        fmt.Println("Error reading:", err)
        return
    }
    // Send a response back to the client
    message := "Hello, client!"
    conn.Write([]byte(message))
    fmt.Println("Message received:", string(buffer[:n]))
}
```
